import{_ as a,o as t,c as i,a3 as o}from"./chunks/framework.Dz5Q8p4s.js";const p=JSON.parse('{"title":"Action-Conditioned and Exploratory World Models","description":"","frontmatter":{"title":"Action-Conditioned and Exploratory World Models","outline":[2,2]},"headers":[],"relativePath":"en/tutorials/world-models.md","filePath":"en/tutorials/world-models.md","lastUpdated":null}'),r={name:"en/tutorials/world-models.md"};function l(n,e,s,d,h,c){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="action-conditioned-and-exploratory-world-models" tabindex="-1">Action-Conditioned and Exploratory World Models <a class="header-anchor" href="#action-conditioned-and-exploratory-world-models" aria-label="Permalink to &quot;Action-Conditioned and Exploratory World Models&quot;">​</a></h1><blockquote><p><strong>Full text (Chinese)</strong>: <a href="/notes/tutorials/world-models">动作条件与探索式世界模型</a><strong>Coverage</strong>: June 2025 – July 2026, with foundational work traced back where needed. <strong>Papers</strong>: <a href="/notes/en/papers/#tut-world-models">177 deep-read notes</a></p></blockquote><div class="warning custom-block"><p class="custom-block-title">About this English page</p><p>The tutorial itself is written in Chinese. This page is its English companion: it gives the complete chapter-by-chapter structure and states what each chapter argues. Every derivation, table, diagram and per-paper breakdown lives in the <a href="/notes/tutorials/world-models">Chinese edition</a>; the <a href="/notes/en/papers/">paper library</a> is fully browsable in English.</p></div><h2 id="what-this-tutorial-is-about" tabindex="-1">What this tutorial is about <a class="header-anchor" href="#what-this-tutorial-is-about" aria-label="Permalink to &quot;What this tutorial is about&quot;">​</a></h2><p>A world model in the video-generation sense is a simulator you can act inside: give it a state and an action, and it returns the next observation. The tutorial argues that video is the natural universal interface for this, because it is the one modality with internet-scale pretraining data and a shared representation across games, driving, indoor scenes and robots.</p><p>It then separates two things that are frequently conflated. <strong>Action-conditioned</strong> world models are judged on whether the generated future obeys the action that was supplied. <strong>Exploratory</strong> world models are judged on whether a place you revisit still looks like the place you left — memory consistency, not action following. Section 1.5 shows how the two relate; Chapter 7.2 names the resulting central tension, <strong>responsiveness versus consistency</strong>, and Chapter 7.3 proposes the persistent state core as the direction that might resolve it.</p><h2 id="chapter-outline" tabindex="-1">Chapter outline <a class="header-anchor" href="#chapter-outline" aria-label="Permalink to &quot;Chapter outline&quot;">​</a></h2><h3 id="chapter-0-—-how-to-use-this-tutorial" tabindex="-1">Chapter 0 — How to use this tutorial <a class="header-anchor" href="#chapter-0-—-how-to-use-this-tutorial" aria-label="Permalink to &quot;Chapter 0 — How to use this tutorial&quot;">​</a></h3><ul><li>0.1 What we are covering</li><li>0.2 Suggested reading paths</li><li>0.3 Scope</li></ul><h3 id="chapter-1-—-concepts-and-intuition" tabindex="-1">Chapter 1 — Concepts and intuition <a class="header-anchor" href="#chapter-1-—-concepts-and-intuition" aria-label="Permalink to &quot;Chapter 1 — Concepts and intuition&quot;">​</a></h3><ul><li>1.1 What a &quot;world model&quot; is</li><li>1.2 Why video is the universal interface for world models</li><li>1.3 Formalising action conditioning</li><li>1.4 Exploratory world models</li><li>1.5 Action-conditioned vs exploratory: differences and connections</li><li>1.6 Capability dimensions for judging a world model</li><li>1.7 Three frameworks for thinking about world models</li></ul><h3 id="chapter-2-—-mathematical-principles-and-key-techniques" tabindex="-1">Chapter 2 — Mathematical principles and key techniques <a class="header-anchor" href="#chapter-2-—-mathematical-principles-and-key-techniques" aria-label="Permalink to &quot;Chapter 2 — Mathematical principles and key techniques&quot;">​</a></h3><ul><li>2.1 The three generative paradigms</li><li>2.2 Latent representations, tokenizers and VAEs</li><li>2.3 Action injection and control interfaces</li><li>2.4 Long-horizon training: the &quot;forcing&quot; family</li><li>2.5 Memory mechanisms — the key to consistency</li><li>2.6 Real-time operation and distillation</li><li>2.7 One-shot consistency vs frame-by-frame interaction: two product routes</li><li>2.8 Latent action learning</li></ul><h3 id="chapter-3-—-task-taxonomy" tabindex="-1">Chapter 3 — Task taxonomy <a class="header-anchor" href="#chapter-3-—-task-taxonomy" aria-label="Permalink to &quot;Chapter 3 — Task taxonomy&quot;">​</a></h3><ul><li>3.1 Action-conditioned future prediction</li><li>3.2 Interactive game worlds (neural game engines)</li><li>3.3 Open-world exploration and navigation</li><li>3.4 Driving world models</li><li>3.5 Embodied AI and robotics: world-action models (WAM)</li><li>3.6 Multi-agent and multiplayer worlds</li><li>3.7 3D / 4D world generation and reconstruction</li><li>3.8 World models as policy, evaluator and data engine</li></ul><h3 id="chapter-4-—-data" tabindex="-1">Chapter 4 — Data <a class="header-anchor" href="#chapter-4-—-data" aria-label="Permalink to &quot;Chapter 4 — Data&quot;">​</a></h3><ul><li>4.1 What makes the data requirements special</li><li>4.2 Game and interaction datasets</li><li>4.3 Driving datasets</li><li>4.4 Embodied and robotic datasets and benchmarks</li><li>4.5 Real-world exploration data</li><li>4.6 The &quot;world model as data engine&quot; paradigm</li></ul><h3 id="chapter-5-—-methods-and-representative-systems" tabindex="-1">Chapter 5 — Methods and representative systems <a class="header-anchor" href="#chapter-5-—-methods-and-representative-systems" aria-label="Permalink to &quot;Chapter 5 — Methods and representative systems&quot;">​</a></h3><ul><li>5.1 Foundational work (2024 – 2025.05) as background</li><li>5.2 Interactive game world models (2025.06 onward)</li><li>5.3 Open-world exploratory world models (2025.06 onward)</li><li>5.4 Driving world models (2025.06 onward)</li><li>5.5 Embodied and robotic world-action models (2025.06 onward)</li><li>5.6 General and unified world models across domains</li></ul><h3 id="chapter-6-—-benchmarks-and-metrics" tabindex="-1">Chapter 6 — Benchmarks and metrics <a class="header-anchor" href="#chapter-6-—-benchmarks-and-metrics" aria-label="Permalink to &quot;Chapter 6 — Benchmarks and metrics&quot;">​</a></h3><ul><li>6.1 General video-generation metrics — necessary, insufficient</li><li>6.2 Action controllability and action following</li><li>6.3 Long-horizon stability and drift resistance</li><li>6.4 Memory consistency — the central exam for exploratory models</li><li>6.5 Physical plausibility</li><li>6.6 3D and geometric consistency</li><li>6.7 Interactive and composite world benchmarks</li><li>6.8 Driving benchmarks</li><li>6.9 Embodied and robotic benchmarks</li><li>6.10 The credibility of a world model used as evaluator</li></ul><h3 id="chapter-7-—-core-challenges-and-research-trends" tabindex="-1">Chapter 7 — Core challenges and research trends <a class="header-anchor" href="#chapter-7-—-core-challenges-and-research-trends" aria-label="Permalink to &quot;Chapter 7 — Core challenges and research trends&quot;">​</a></h3><ul><li>7.1 Three technical challenges common to every domain</li><li>7.2 The core tension: responsiveness vs consistency</li><li>7.3 The persistent state core</li><li>7.4 Physical plausibility and causality</li><li>7.5 Three macro trends</li><li>7.6 World models as infrastructure</li><li>7.7 Open problems worth working on</li></ul><h3 id="chapter-8-—-paper-by-paper-walkthrough-with-links-2025-06–2026-07" tabindex="-1">Chapter 8 — Paper-by-paper walkthrough with links (2025.06–2026.07) <a class="header-anchor" href="#chapter-8-—-paper-by-paper-walkthrough-with-links-2025-06–2026-07" aria-label="Permalink to &quot;Chapter 8 — Paper-by-paper walkthrough with links (2025.06–2026.07)&quot;">​</a></h3><p>Surveys, positions and definitions; interactive game and multiplayer world models; open-world exploration, 3D/4D and memory; driving world models; embodied world-action models; training, efficiency and general techniques; benchmarks, evaluation and datasets; curated community resources; and product/engineering milestones that are not papers.</p><h2 id="related-tutorials" tabindex="-1">Related tutorials <a class="header-anchor" href="#related-tutorials" aria-label="Permalink to &quot;Related tutorials&quot;">​</a></h2><ul><li><a href="/notes/en/tutorials/world-action-models">World-Action Models</a> — the subset of world models built to drive action</li><li><a href="/notes/en/tutorials/autoregressive">Autoregressive Video Generation</a> — the causal machinery interactive world models are built on</li><li><a href="/notes/en/tutorials/video-for-embodied-ai">Video Generation for Embodied AI</a> — the five roles video plays for robots</li></ul>',27)])])}const m=a(r,[["render",l]]);export{p as __pageData,m as default};
